save(75,dict(paragraphs=["Nilim Kumar writes poetry and prose in Assamese, with work that has reached readers in several languages. His selected poems appear in English as I'm Your Poet, translated by Dibyajyoti Sarma and published by Red River. His poems often begin with familiar gestures or objects and let them open into an unexpected, sometimes unsettling imaginative space.","The poems published here bring that movement into questions of intimacy and coexistence. A meal shared by two ageing lovers approaches mortality; a beautiful curve becomes an invitation and a danger. In the Afruza poems, dates offered during Ramadan and a temple imagined beside a mosque within one heart turn everyday hospitality into a language of fellowship across religious divisions."],sources=[source('Red River — I’m Your Poet','https://redriverpress.in/product/im-your-poet/',['Assamese poet and prose writer','Selected poetry book title and authorship','Translation circulation']),source('Dibyajyoti Sarma — translator’s book announcement','https://www.goodreads.com/author/show/2958477.Dibyajyoti_Sarma/blog?page=4',['15 October 2022 author blog announcement of own translation of Nilim Kumar','Acknowledges additional translations by Anindita Kar and Nabina Das'],access='search_index_excerpt'),source('Poetry International — Nilim Kumar','https://www.poetryinternational.com/en/poets-poems/poets/poet/102-23807_Kumar/',['Assamese poetry and prose, translated into several languages'],access='search_index_excerpt')],books=[dict(title="I'm Your Poet",detail='Selected poems in English translation by Dibyajyoti Sarma. Red River.',url='https://redriverpress.in/product/im-your-poet/')],identity_match='Assamese writing, Guwahati association and distinctive bibliography agree between captured biography, publisher and Poetry International.',poems_read=[dict(id=724,title='AFRUZA SENT ME SOME DATES',basis='Full captured English text read: Ramadan dates, desert palms, brotherhood and secularism; underlying Assamese original not available in this source.'),dict(id=472,title='The Temple of Afruza Akhtar',basis='Full published English translation read; named credit Bibekananda Choudhury preserved. Temple/mosque in heart, ethical building materials and twins.'),dict(id=47,title='Two Poems',basis='Both complete published English poems read: dining with shadows at hotel Death; beautiful/dangerous curve and return home. Nirendra Nath Thakuria credit preserved.')],limitations=['Close reading is of available published English versions, not a claim of inspecting Assamese originals.','Book translator credit does not replace the different translators credited to magazine poems.','No current collection total; sources give dated counts of 17 and 21.','Blog profile gives conflicting birth year 1962 versus publisher 1961; birth year omitted.','No new university syllabus or award claims needed; original biography preserved.'],research_leads=[dict(url='https://ramanathbhattacharyafoundation.org/padmanath-vidyabinod-memorial-awards.html',access='search_index_excerpt; direct fetch error',finding='Award body identifies 2019 recipient and books; not expanded into reader narrative.'),dict(url='https://nilimkumar.blogspot.com/p/blog-page_03.html',access='search_index_excerpt',finding='Conflicting 1962 birth year; not relied on.')],next_action='Independent author/editor review, including underlying original-language and translation provenance if supplied.'))
